draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // certificate
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2 - 50, H/2 - 70, 100, 50);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.strokeRect(W/2 - 50, H/2 - 70, 100, 50);
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Achievement', W/2, H/2 - 45);

  // rising motion
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();

  ctx.restore();
}
